// ─────────────────────────────────────────────────────────────────────
// Genio AI – Email Formatter  (includes birthday card + timesheet routing)
// ─────────────────────────────────────────────────────────────────────

const body = $input.first().json.body || $input.first().json;

const actionType  = body.action_type  || 'unknown';
const userName    = body.user_name    || 'Unknown User';
const userEmail   = body.user_email   || 'unknown@company.com';
const rawTime     = body.timestamp    || new Date().toISOString();
const data        = body.form_data    || {};
const appOrigin   = body.app_origin   || '';

// ── Format timestamp ──────────────────────────────────────────────────
const timestamp = new Date(rawTime).toLocaleString('en-IN', {
  timeZone: 'Asia/Kolkata',
  year: 'numeric', month: 'long', day: 'numeric',
  hour: '2-digit', minute: '2-digit'
});

// ── Destination email addresses ───────────────────────────────────────
// TODO: Replace these with your actual team email addresses
const HR_EMAIL         = 'hr@company.com';
const IT_EMAIL         = 'it-support@company.com';
const ADMIN_EMAIL      = 'admin@company.com';
const COMPLIANCE_EMAIL = 'compliance@company.com';
const FEEDBACK_EMAIL   = 'feedback@company.com';

// ── Build HTML table from form data ───────────────────────────────────
function formatTable(fields) {
  return Object.entries(fields)
    .filter(([, v]) => v && String(v).trim())
    .map(([k, v]) => {
      const label = k.replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
      return `
        <tr>
          <td style="padding:10px 16px;font-weight:600;color:#555;background:#f8f9fc;border:1px solid #e8ecf0;width:190px;vertical-align:top;font-size:13px">${label}</td>
          <td style="padding:10px 16px;color:#333;border:1px solid #e8ecf0;font-size:13px">${v}</td>
        </tr>`;
    }).join('');
}

// ── Build full HTML email ─────────────────────────────────────────────
function buildEmail(icon, title, intro, fields, footerNote, urgencyBadge) {
  const tableFields = {
    ...fields,
    'Employee Name':  userName,
    'Employee Email': userEmail,
    'Submitted At':   timestamp
  };
  const tableHTML = formatTable(tableFields);
  const urgencyHTML = urgencyBadge
    ? `<div style="display:inline-block;padding:4px 12px;border-radius:20px;font-size:12px;font-weight:700;background:${urgencyBadge.bg};color:${urgencyBadge.color};margin-bottom:16px">${urgencyBadge.label}</div>`
    : '';
  const footerHTML = footerNote
    ? `<div style="margin-top:20px;padding:14px 16px;background:#f0ecff;border-left:4px solid #6c47ff;border-radius:0 8px 8px 0;font-size:13px;color:#4f30d4">${footerNote}</div>`
    : '';

  return `
<!DOCTYPE html>
<html>
<head><meta charset="UTF-8"></head>
<body style="margin:0;padding:20px;background:#f0f2f5;font-family:Segoe UI,Arial,sans-serif">
  <div style="max-width:600px;margin:0 auto;border-radius:16px;overflow:hidden;box-shadow:0 4px 24px rgba(0,0,0,0.12)">

    <!-- Header -->
    <div style="background:linear-gradient(135deg,#6c47ff,#00c2a8);padding:28px 32px;color:white">
      <div style="font-size:36px;margin-bottom:10px">${icon}</div>
      <h1 style="margin:0 0 6px;font-size:22px;font-weight:700">${title}</h1>
      <p style="margin:0;opacity:0.85;font-size:13px">Genio AI Workspace Assistant · Bonfiglioli</p>
    </div>

    <!-- Body -->
    <div style="padding:28px 32px;background:#ffffff">
      ${urgencyHTML}
      <p style="color:#444;margin:0 0 20px;font-size:14px;line-height:1.6">${intro}</p>
      <table style="border-collapse:collapse;width:100%">${tableHTML}</table>
      ${footerHTML}
    </div>

    <!-- Footer -->
    <div style="padding:18px 32px;background:#f8f9fc;border-top:1px solid #e8ecf0;text-align:center">
      <p style="color:#999;font-size:12px;margin:0">This email was sent automatically via <strong>Genio AI</strong> · Powered by Bonfiglioli</p>
      <p style="color:#bbb;font-size:11px;margin:4px 0 0">Do not reply to this email · Contact the sender directly</p>
    </div>
  </div>
</body>
</html>`;
}

// ── Urgency badge helper ──────────────────────────────────────────────
function urgencyBadge(urgency) {
  if (!urgency) return null;
  const u = urgency.toLowerCase();
  if (u.includes('critical') || u.includes('emergency')) return { label: '🚨 ' + urgency, bg: '#fde8e8', color: '#c0392b' };
  if (u.includes('urgent') || u.includes('high'))        return { label: '⚠️ ' + urgency, bg: '#fff3cd', color: '#856404' };
  return null;
}

// ── Route by action type ──────────────────────────────────────────────
let subject, toEmail, htmlBody, confirmationNote;

switch (actionType) {

  case 'birthday_card': {
    const recipientName  = data.recipient_name  || 'Colleague';
    const recipientEmail = data.recipient_email || userEmail;
    const personalMsg    = data.message         || '';
    const imageUrl       = appOrigin ? `${appOrigin}/bday%20card.jpg` : '';

    subject = `🎂 Happy Birthday, ${recipientName}! — from ${userName}`;
    toEmail = recipientEmail;

    const imgBlock = imageUrl
      ? `<div style="text-align:center;margin:24px 0">
           <img src="${imageUrl}" alt="Birthday Card" style="max-width:100%;border-radius:12px;box-shadow:0 4px 20px rgba(0,0,0,.18)" />
         </div>`
      : '';
    const msgBlock = personalMsg
      ? `<div style="margin:20px 0;padding:16px 20px;background:#fff9f0;border-left:4px solid #ffb347;border-radius:0 8px 8px 0;font-size:14px;color:#555;font-style:italic;line-height:1.6">
           "${personalMsg}"
         </div>`
      : '';

    htmlBody = `<!DOCTYPE html><html><head><meta charset="UTF-8"></head>
<body style="margin:0;padding:20px;background:#f0f2f5;font-family:Segoe UI,Arial,sans-serif">
  <div style="max-width:600px;margin:0 auto;border-radius:16px;overflow:hidden;box-shadow:0 4px 24px rgba(0,0,0,.12)">
    <div style="background:linear-gradient(135deg,#ff6b6b,#feca57);padding:32px;color:white;text-align:center">
      <div style="font-size:56px;margin-bottom:10px">🎂</div>
      <h1 style="margin:0 0 8px;font-size:28px;font-weight:700">Happy Birthday, ${recipientName}!</h1>
      <p style="margin:0;opacity:.9;font-size:14px">A birthday wish from <strong>${userName}</strong></p>
    </div>
    <div style="padding:28px 32px;background:#fff">
      ${imgBlock}
      <p style="color:#444;font-size:16px;text-align:center;line-height:1.8;margin:0 0 16px">
        🎉 Wishing you a fantastic birthday full of joy, laughter, and everything you deserve!
      </p>
      ${msgBlock}
      <p style="color:#bbb;font-size:12px;text-align:center;margin:24px 0 0">
        Sent by <strong>${userName}</strong> via <strong>Genio AI · Bonfiglioli</strong>
      </p>
    </div>
  </div>
</body></html>`;

    confirmationNote = `Your birthday card has been sent to <strong>${recipientName}</strong> at ${recipientEmail}.`;
    break;
  }

  case 'apply_leave':
    subject = `📅 Leave Request: ${data.leave_type || 'Leave'} — ${userName}`;
    toEmail = HR_EMAIL;
    htmlBody = buildEmail(
      '📅', 'Leave Application',
      `<strong>${userName}</strong> has submitted a leave request via Genio AI. Please review and approve or reject accordingly.`,
      data,
      `Please reply directly to <a href="mailto:${userEmail}" style="color:#6c47ff">${userEmail}</a> with your decision.`,
      urgencyBadge(data.urgency)
    );
    confirmationNote = `Your leave request (${data.leave_type || 'Leave'}) from ${data.start_date || '?'} to ${data.end_date || '?'} has been submitted to HR.`;
    break;

  case 'it_ticket':
    subject = `🛠️ IT Ticket [${data.priority || 'Medium'}]: ${data.subject || 'Support Request'} — ${userName}`;
    toEmail = IT_EMAIL;
    htmlBody = buildEmail(
      '🛠️', 'IT Support Ticket',
      `<strong>${userName}</strong> has raised an IT support ticket. Please assign and resolve within your SLA.`,
      data,
      `Contact employee: <a href="mailto:${userEmail}" style="color:#6c47ff">${userEmail}</a>`,
      urgencyBadge(data.priority)
    );
    confirmationNote = `Your IT ticket "${data.subject || 'Support Request'}" [${data.priority || 'Medium'} priority] has been submitted to the IT team.`;
    break;

  case 'access_request':
    subject = `🔑 Access Request: ${data.system_name || 'System'} — ${userName}`;
    toEmail = IT_EMAIL;
    htmlBody = buildEmail(
      '🔑', 'System Access Request',
      `<strong>${userName}</strong> has requested access to a system or application. Please verify and provision accordingly.`,
      data,
      `Contact: <a href="mailto:${userEmail}" style="color:#6c47ff">${userEmail}</a>`,
      null
    );
    confirmationNote = `Your access request for ${data.system_name || 'the system'} has been submitted to the IT team.`;
    break;

  case 'software_request':
    subject = `💻 Software Request: ${data.software_name || 'Software'} — ${userName}`;
    toEmail = IT_EMAIL;
    htmlBody = buildEmail(
      '💻', 'Software / License Request',
      `<strong>${userName}</strong> has requested a software license or installation. Please review and procure if approved.`,
      data,
      `Contact: <a href="mailto:${userEmail}" style="color:#6c47ff">${userEmail}</a>`,
      null
    );
    confirmationNote = `Your software request for ${data.software_name || 'the software'} has been submitted to the IT team.`;
    break;

  case 'book_room':
    subject = `🏢 Room Booking: ${data.room || 'Meeting Room'} on ${data.date || 'TBD'} — ${userName}`;
    toEmail = ADMIN_EMAIL;
    htmlBody = buildEmail(
      '🏢', 'Meeting Room Booking',
      `<strong>${userName}</strong> has requested a meeting room booking. Please confirm availability and respond.`,
      data,
      `Please confirm or suggest an alternative and reply to <a href="mailto:${userEmail}" style="color:#6c47ff">${userEmail}</a>.`,
      null
    );
    confirmationNote = `Your room booking request for ${data.room || 'the meeting room'} on ${data.date || 'the requested date'} has been submitted to Admin.`;
    break;

  case 'travel_request':
    subject = `✈️ Travel Request: ${data.destination || 'Travel'} — ${userName}`;
    toEmail = ADMIN_EMAIL;
    htmlBody = buildEmail(
      '✈️', 'Business Travel Request',
      `<strong>${userName}</strong> has submitted a business travel request for approval. Please arrange travel and accommodation.`,
      data,
      `Contact employee for travel documents: <a href="mailto:${userEmail}" style="color:#6c47ff">${userEmail}</a>`,
      null
    );
    confirmationNote = `Your travel request to ${data.destination || 'your destination'} has been submitted to Admin.`;
    break;

  case 'office_supplies':
    subject = `📦 Office Supplies Request — ${userName}`;
    toEmail = ADMIN_EMAIL;
    htmlBody = buildEmail(
      '📦', 'Office Supplies Request',
      `<strong>${userName}</strong> has requested office supplies. Please process and arrange delivery.`,
      data,
      `Contact: <a href="mailto:${userEmail}" style="color:#6c47ff">${userEmail}</a>`,
      urgencyBadge(data.urgency)
    );
    confirmationNote = `Your office supplies request has been submitted to Admin.`;
    break;

  case 'facilities':
    subject = `🔧 Facilities: ${data.issue_type || 'Issue'} at ${data.location || 'Unknown Location'} — ${data.urgency || 'Normal'}`;
    toEmail = ADMIN_EMAIL;
    htmlBody = buildEmail(
      '🔧', 'Facilities / Maintenance Request',
      `<strong>${userName}</strong> has reported a facilities issue that requires attention. Please attend promptly.`,
      data,
      `Contact employee: <a href="mailto:${userEmail}" style="color:#6c47ff">${userEmail}</a>`,
      urgencyBadge(data.urgency)
    );
    confirmationNote = `Your facilities request (${data.issue_type || 'Maintenance'} at ${data.location || 'the location'}) has been submitted.`;
    break;

  case 'training_request':
    subject = `🎓 Training Request: ${data.course_name || 'Training'} — ${userName}`;
    toEmail = HR_EMAIL;
    htmlBody = buildEmail(
      '🎓', 'Training / Learning Request',
      `<strong>${userName}</strong> has requested a training or learning program. Please review and approve.`,
      data,
      `Contact: <a href="mailto:${userEmail}" style="color:#6c47ff">${userEmail}</a>`,
      null
    );
    confirmationNote = `Your training request for "${data.course_name || 'the course'}" has been submitted to HR.`;
    break;

  case 'compliance_query':
    subject = `⚖️ Compliance Query: ${data.topic || 'Compliance'} — ${userName}`;
    toEmail = COMPLIANCE_EMAIL;
    htmlBody = buildEmail(
      '⚖️', 'Compliance / Legal Query',
      `<strong>${userName}</strong> has submitted a compliance or legal query. Please respond within 2 business days.`,
      data,
      `Contact: <a href="mailto:${userEmail}" style="color:#6c47ff">${userEmail}</a>`,
      urgencyBadge(data.urgency)
    );
    confirmationNote = `Your compliance query about "${data.topic || 'compliance'}" has been submitted.`;
    break;

  case 'submit_feedback':
    subject = `💬 Feedback: ${data.feedback_type || 'Feedback'} — ${userName}`;
    toEmail = FEEDBACK_EMAIL;
    htmlBody = buildEmail(
      '💬', 'Employee Feedback',
      `<strong>${userName}</strong> has submitted feedback via Genio AI. Please review and action as appropriate.`,
      data,
      null,
      null
    );
    confirmationNote = `Your feedback has been submitted. Thank you for sharing!`;
    break;

  case 'payroll_query':
    subject = `💵 Payroll Query: ${data.query_type || 'Query'} — ${userName}`;
    toEmail = HR_EMAIL;
    htmlBody = buildEmail(
      '💵', 'Payroll Query',
      `<strong>${userName}</strong> has a payroll query that needs attention. Please review and respond within 2 business days.`,
      data,
      `Contact: <a href="mailto:${userEmail}" style="color:#6c47ff">${userEmail}</a>`,
      null
    );
    confirmationNote = `Your payroll query (${data.query_type || 'Query'}) has been submitted to HR/Finance.`;
    break;

  case 'benefits':
    subject = `🎁 Benefits Query: ${data.benefit_type || 'Benefits'} — ${userName}`;
    toEmail = HR_EMAIL;
    htmlBody = buildEmail(
      '🎁', 'Employee Benefits Query',
      `<strong>${userName}</strong> has a question about employee benefits. Please respond.`,
      data,
      `Contact: <a href="mailto:${userEmail}" style="color:#6c47ff">${userEmail}</a>`,
      null
    );
    confirmationNote = `Your benefits query about ${data.benefit_type || 'benefits'} has been submitted to HR.`;
    break;

  case 'hr_policies':
    subject = `📋 HR Policy Query: ${data.policy_area || 'HR Policy'} — ${userName}`;
    toEmail = HR_EMAIL;
    htmlBody = buildEmail(
      '📋', 'HR Policy Query',
      `<strong>${userName}</strong> has a question about HR policies. Please respond directly.`,
      data,
      `Contact: <a href="mailto:${userEmail}" style="color:#6c47ff">${userEmail}</a>`,
      null
    );
    confirmationNote = `Your HR policy query about "${data.policy_area || 'policies'}" has been submitted.`;
    break;

  default:
    subject = `Genio AI Request: ${actionType.replace(/_/g, ' ')} — ${userName}`;
    toEmail = HR_EMAIL;
    htmlBody = buildEmail(
      '📋', 'Workspace Request',
      `<strong>${userName}</strong> has submitted a request via Genio AI.`,
      { action_type: actionType, ...data },
      null,
      null
    );
    confirmationNote = `Your request has been submitted successfully.`;
}

// ── Build confirmation email to user ──────────────────────────────────
const confirmSubject = `✅ Request Confirmed: ${subject.replace(/^[^a-zA-Z]+/, '')}`;
const confirmHtml = `
<!DOCTYPE html>
<html>
<head><meta charset="UTF-8"></head>
<body style="margin:0;padding:20px;background:#f0f2f5;font-family:Segoe UI,Arial,sans-serif">
  <div style="max-width:520px;margin:0 auto;border-radius:16px;overflow:hidden;box-shadow:0 4px 24px rgba(0,0,0,0.12)">
    <div style="background:linear-gradient(135deg,#6c47ff,#00c2a8);padding:28px 32px;color:white">
      <div style="font-size:36px;margin-bottom:10px">✅</div>
      <h1 style="margin:0 0 6px;font-size:20px;font-weight:700">Request Submitted!</h1>
      <p style="margin:0;opacity:0.85;font-size:13px">Genio AI · Bonfiglioli</p>
    </div>
    <div style="padding:28px 32px;background:#fff">
      <p style="color:#333;font-size:15px">Hi <strong>${userName}</strong>,</p>
      <p style="color:#555;font-size:14px;line-height:1.6">${confirmationNote}</p>
      <div style="margin:20px 0;padding:16px;background:#f0ecff;border-radius:10px">
        <p style="margin:0;font-size:13px;color:#6c47ff">⏱ You will receive a response from the relevant team shortly.</p>
      </div>
      <table style="border-collapse:collapse;width:100%">
        <tr>
          <td style="padding:8px 12px;font-weight:600;color:#555;background:#f8f9fc;border:1px solid #e8ecf0;font-size:13px">Request Type</td>
          <td style="padding:8px 12px;color:#333;border:1px solid #e8ecf0;font-size:13px">${actionType.replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase())}</td>
        </tr>
        <tr>
          <td style="padding:8px 12px;font-weight:600;color:#555;background:#f8f9fc;border:1px solid #e8ecf0;font-size:13px">Submitted At</td>
          <td style="padding:8px 12px;color:#333;border:1px solid #e8ecf0;font-size:13px">${timestamp}</td>
        </tr>
      </table>
    </div>
    <div style="padding:16px 32px;background:#f8f9fc;border-top:1px solid #e8ecf0;text-align:center">
      <p style="color:#999;font-size:12px;margin:0">Automated by <strong>Genio AI</strong> · Bonfiglioli</p>
    </div>
  </div>
</body>
</html>`;

return [{
  json: {
    subject,
    toEmail,
    htmlBody,
    confirmSubject,
    confirmHtml,
    userEmail,
    userName,
    actionType,
    timestamp
  }
}];

parameters.responseBody:
={
  "success": true,
  "message": "Request submitted successfully! Emails have been sent.",
  "action_type": "{{ $('Format Email').item.json.actionType }}",
  "submitted_at": "{{ $('Format Email').item.json.timestamp }}"
}
